import sys
input = sys.stdin.read

def find_smallest_n(shuffled, remembered_substring):
    len_remembered = len(remembered_substring)
    min_n = None
    for i in range(len(shuffled)):
        if shuffled[i:].find(remembered_substring) != -1:
            possible_n_length = len(shuffled) - i - len_remembered
            possible_n_string = shuffled[:i] + remembered_substring
            if len(possible_n_string) == possible_n_length:
                if (possible_n_string[0] != '0' or possible_n_string == '0'):
                    if min_n is None or possible_n_string < min_n:
                        min_n = possible_n_string
    return min_n

def main():
    data = input().strip().split()
    shuffled = data[0]
    remembered = data[1]

    result = find_smallest_n(shuffled, remembered)
    if result is not None:
        print(result)

